using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;

namespace AdhdWarrior {
 public class DailyTemplate {
  public string Id {get;set;} public string Title {get;set;} public int XP {get;set;} public bool Enabled {get;set;} public List<int> Weekdays {get;set;} public string Window {get;set;}
  public DailyTemplate(){Id=Guid.NewGuid().ToString();Title="";XP=10;Enabled=true;Weekdays=Enumerable.Range(1,7).ToList();Window="Morning";}
 }
 public class PendingReward {public string Id {get;set;} public string GearId {get;set;} public string Source {get;set;} public PendingReward(){Id=Guid.NewGuid().ToString();}}
 public static class DailyTemplatesEngine {
  public static readonly int[] Milestones={3,7,14,30,60};
  public static List<DailyTemplate> Defaults(){return new List<DailyTemplate>{
   New("Read One chapter of the bible",50),New("Take a shower",15),New("Brush teeth",10),New("Drink at least 32oz of water",12)};}
  static DailyTemplate New(string title,int xp){return new DailyTemplate {Title=title,XP=xp};}
  public static bool Applies(DailyTemplate t,DateTime day){return t.Enabled&&t.Weekdays.Contains((int)day.DayOfWeek+1);}
  public static bool EnsureToday(SaveData data,DateTime day){
   if(!data.AutoGenerateDaily)return false;string key=day.ToString("yyyy-MM-dd");bool changed=false;
   foreach(var t in data.DailyTemplates.Where(x=>Applies(x,day))){if(data.Quests.Any(q=>q.DailyTemplateId==t.Id&&q.GeneratedDay==key))continue;data.Quests.Add(new Quest {Title=t.Title,XP=t.XP,Rarity="Common",Due=key,DailyTemplateId=t.Id,GeneratedDay=key});changed=true;}
   return changed;
  }
  public static void ApplyToday(SaveData data,DateTime day){
   string key=day.ToString("yyyy-MM-dd");var map=data.DailyTemplates.ToDictionary(x=>x.Id);
   data.Quests.RemoveAll(q=>q.GeneratedDay==key&&!q.Done&&(!map.ContainsKey(q.DailyTemplateId)||!Applies(map[q.DailyTemplateId],day)));
   foreach(var q in data.Quests.Where(q=>q.GeneratedDay==key&&!q.Done&&map.ContainsKey(q.DailyTemplateId))){var t=map[q.DailyTemplateId];q.Title=t.Title;q.XP=t.XP;q.Rarity="Common";}
   EnsureToday(data,day);
  }
  public static void ProcessMilestones(SaveData data){
   foreach(int milestone in Milestones.Where(x=>data.Journey.Completions>=x&&!data.ClaimedMilestones.Contains(x))){
    Journey.AwardNextGear(data,"Consistency "+milestone+" completions");data.ClaimedMilestones.Add(milestone);
   }
  }
  public static bool ClaimPendingAutomatically(SaveData data){if(data.PendingRewards==null||data.PendingRewards.Count==0)return false;foreach(var reward in data.PendingRewards.ToList())Journey.AwardNextGear(data,reward.Source);data.PendingRewards.Clear();return true;}
  public static void Validate(SaveData data){
   if(data.DailyTemplates==null||data.PendingRewards==null||data.ClaimedMilestones==null||data.DailyTemplates.Count>200||data.PendingRewards.Count>100)throw new InvalidDataException("Invalid daily template or reward data.");
   var ids=new HashSet<string>();Guid id;
   foreach(var t in data.DailyTemplates)if(t==null||!Guid.TryParse(t.Id,out id)||!ids.Add(t.Id)||String.IsNullOrWhiteSpace(t.Title)||t.Title.Length>500||t.XP<5||t.XP>1000||t.Weekdays==null||t.Weekdays.Count<1||t.Weekdays.Distinct().Count()!=t.Weekdays.Count||t.Weekdays.Any(x=>x<1||x>7)||!new[]{"Morning","Afternoon","Evening"}.Contains(t.Window))throw new InvalidDataException("The backup contains an invalid daily template.");
   ids.Clear();var gearIds=new HashSet<string>();foreach(var r in data.PendingRewards)if(r==null||!Guid.TryParse(r.Id,out id)||!ids.Add(r.Id)||String.IsNullOrWhiteSpace(r.Source)||r.Source.Length>500||!GearCatalog.All.Any(g=>g.Id==r.GearId)||data.Journey.Gear.Contains(r.GearId)||!gearIds.Add(r.GearId))throw new InvalidDataException("The backup contains an invalid pending reward.");
   if(data.ClaimedMilestones.Distinct().Count()!=data.ClaimedMilestones.Count||data.ClaimedMilestones.Any(x=>!Milestones.Contains(x)))throw new InvalidDataException("The backup contains invalid consistency milestones.");
  }
 }
 public partial class MainWindow {
  void ShowDailyTemplates(){
   var toggle=new CheckBox {Text="Create today's matching quests automatically",Checked=data.AutoGenerateDaily,AutoSize=true,Padding=new Padding(8),ForeColor=Theme.Text};toggle.CheckedChanged+=(s,e)=>Change(()=>{data.AutoGenerateDaily=toggle.Checked;DailyTemplatesEngine.ApplyToday(data,DateTime.Today);},toggle.Checked?"Daily quest generation enabled.":"Daily quest generation paused.");cards.Controls.Add(toggle);
   cards.Controls.Add(Button("+ Add daily template",()=>EditDailyTemplate(null)));
   Note("Enabled templates create one Common quest on their selected weekdays. Editing or disabling a template updates today's unfinished generated quest.");
   foreach(var template in data.DailyTemplates.ToList()){var t=template;var days=String.Join(" · ",DayNames(t.Weekdays));var enabled=Button(t.Enabled?"Pause":"Enable",()=>Change(()=>{t.Enabled=!t.Enabled;DailyTemplatesEngine.ApplyToday(data,DateTime.Today);},t.Enabled?"Template paused.":"Template enabled."));var edit=Button("Edit",()=>EditDailyTemplate(t));var remove=Button("Remove",()=>{if(MessageBox.Show(this,"Remove ‘"+t.Title+"’? Today's unfinished generated quest will also be removed.","Remove template",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)Change(()=>{data.DailyTemplates.Remove(t);DailyTemplatesEngine.ApplyToday(data,DateTime.Today);},"Daily template removed.");});AdventureCard(t.Title,(t.Enabled?"Enabled":"Paused")+" · "+t.Window+" · "+t.XP+" XP\n"+days,Artwork("forest-twilight"),0,1,enabled,edit,remove);}
  }
  static IEnumerable<string> DayNames(IEnumerable<int> days){string[] names={"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};return days.OrderBy(x=>x).Select(x=>names[x-1]);}
  void EditDailyTemplate(DailyTemplate original){using(var editor=new DailyTemplateEditor(original))if(editor.ShowDialog(this)==DialogResult.OK)Change(()=>{if(original==null)data.DailyTemplates.Add(editor.Result);else data.DailyTemplates[data.DailyTemplates.IndexOf(original)]=editor.Result;DailyTemplatesEngine.ApplyToday(data,DateTime.Today);},"Daily template saved.");}
  void ShowRewards(){
   Note("Every step counts.\n\n"+data.Quests.Count(q=>q.Done)+" quests completed • "+data.XP+" lifetime XP • "+data.Coins+" coins available");
   if(data.PendingRewards.Count==0)Note("Gear rewards are claimed automatically into your current avatar set. Consistency rewards unlock at 3, 7, 14, 30, and 60 total completions.");
   foreach(var pending in data.PendingRewards.ToList()){var reward=pending;var gear=GearCatalog.All.Single(x=>x.Id==reward.GearId);AdventureCard(gear.Name,gear.Rarity+" "+gear.Slot+"\n"+reward.Source,Artwork(GearSheets[gear.Sheet],gear.Tile),0,1,Button("Claim reward",()=>Change(()=>{if(!data.Journey.Gear.Contains(reward.GearId))data.Journey.Gear.Add(reward.GearId);data.PendingRewards.Remove(reward);Journey.Log(data.Journey,"Claimed "+gear.Name+" from "+reward.Source+".");},"Reward claimed: "+gear.Name+".")));}
   Note(Progression.NextLabel(data.XP)+"\n\nQuest rewards: XP you choose, plus 1 coin per 5 XP. Completing a quest also completes its remaining steps.");foreach(var entry in data.Journey.Journal)Note(entry);
  }
 }
 public class DailyTemplateEditor : Form {
  public DailyTemplate Result;TextBox title=new TextBox();NumericUpDown xp=new NumericUpDown();ComboBox window=new ComboBox();CheckBox enabled=new CheckBox();CheckBox[] days=new CheckBox[7];DailyTemplate original;
  public DailyTemplateEditor(DailyTemplate item){original=item;Text=item==null?"New daily template":"Edit daily template";Size=new Size(570,430);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Theme.Canvas;ForeColor=Theme.Text;var form=new FlowLayoutPanel {Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(24)};Controls.Add(form);form.Controls.Add(new Label {Text="Quest title",AutoSize=true});title.Width=490;title.MaxLength=500;Theme.StyleInput(title);form.Controls.Add(title);var row=new FlowLayoutPanel {AutoSize=true};row.Controls.Add(new Label {Text="XP",AutoSize=true,Padding=new Padding(0,7,6,0)});xp.Minimum=5;xp.Maximum=1000;xp.Value=10;row.Controls.Add(xp);row.Controls.Add(new Label {Text="Time of day",AutoSize=true,Padding=new Padding(16,7,6,0)});window.Items.AddRange(new object[]{"Morning","Afternoon","Evening"});window.DropDownStyle=ComboBoxStyle.DropDownList;window.SelectedIndex=0;row.Controls.Add(window);enabled.Text="Enabled";enabled.Checked=true;enabled.AutoSize=true;enabled.Padding=new Padding(14,5,0,0);row.Controls.Add(enabled);form.Controls.Add(row);form.Controls.Add(new Label {Text="Active weekdays",AutoSize=true,Margin=new Padding(0,14,0,4)});var dayRow=new FlowLayoutPanel {AutoSize=true};string[] names={"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};for(int i=0;i<7;i++){days[i]=new CheckBox {Text=names[i],Checked=true,AutoSize=true};dayRow.Controls.Add(days[i]);}form.Controls.Add(dayRow);var buttons=new FlowLayoutPanel {AutoSize=true,Margin=new Padding(0,22,0,0)};var save=new ThemedButton {Text="Save template",AutoSize=true};var cancel=new ThemedButton {Text="Cancel",AutoSize=true,DialogResult=DialogResult.Cancel};Theme.StyleButton(save,true);Theme.StyleButton(cancel);buttons.Controls.Add(save);buttons.Controls.Add(cancel);form.Controls.Add(buttons);AcceptButton=save;CancelButton=cancel;if(item!=null){title.Text=item.Title;xp.Value=item.XP;window.SelectedItem=item.Window;enabled.Checked=item.Enabled;for(int i=0;i<7;i++)days[i].Checked=item.Weekdays.Contains(i+1);}save.Click+=(s,e)=>{var active=Enumerable.Range(0,7).Where(i=>days[i].Checked).Select(i=>i+1).ToList();if(String.IsNullOrWhiteSpace(title.Text)||active.Count==0){MessageBox.Show(this,"Add a title and select at least one weekday.");return;}Result=new DailyTemplate {Id=original==null?Guid.NewGuid().ToString():original.Id,Title=title.Text.Trim(),XP=(int)xp.Value,Window=(string)window.SelectedItem,Enabled=enabled.Checked,Weekdays=active};DialogResult=DialogResult.OK;};}
 }
}
